function u_s_out = mfun_imfvc_flux_torque_controller(ref, fbk_in, p)
%MFUN_IMFVC_FLUX_TORQUE_CONTROLLER Block FluxTorqueController of the control system.
%   FluxTorqueController of motulator. Generated by motulator_export from the MATLAB
%   port of motulator and called by the MATLAB Function block of the library of
%   motulator, whose folder motulator.setup adds to the MATLAB path. The parameters are
%   the fields of the struct p (from the mask, [] as NaN). The state is in persistent
%   variables, of which each MATLAB Function block has its own copy.
persistent self
if isempty(self)
    % Machine model (InductionMachineInvGammaPars)
    par = struct('n_p', p.par_n_p, 'R_s', p.par_R_s, 'R_R', p.par_R_R, ...
        'L_sgm', p.par_L_sgm, 'L_M', p.par_L_M);
    self = im_flux_torque_ctrl_init(par, p.alpha_psi, p.alpha_tau, p.alpha_i);
end
fbk = im_observer_outputs_unpack(fbk_in);
[self, u_s] = im_flux_torque_ctrl_compute_output(self, ref(1), ref(2), fbk);
u_s_out = complex_out(u_s);
self = im_flux_torque_ctrl_update(self, p.T_s, fbk);
end

function s = im_observer_outputs_unpack(u)
%IM_OBSERVER_OUTPUTS_UNPACK Struct of the signal vector u.
s = struct( ...
    'i_s', complex(u(1), u(2)), ...
    'u_s', complex(u(3), u(4)), ...
    'u_s_zoh', complex(u(5), u(6)), ...
    'psi_s', complex(u(7), u(8)), ...
    'psi_R', complex(u(9), u(10)), ...
    'tau_M', u(11), ...
    'w_c', u(12), ...
    'w_s', u(13), ...
    'w_r', u(14), ...
    'w_m', u(15), ...
    'w_M', u(16), ...
    'theta_c', u(17), ...
    'e_o', complex(u(18), u(19)), ...
    'eps', u(20), ...
    'h', u(21));
end

function y = complex_out(z)
%COMPLEX_OUT Signal [real part; imaginary part] of a complex number.
y = [real(z); imag(z)];
end

function self = im_flux_torque_ctrl_init(par, alpha_psi, alpha_tau, alpha_i)
%IM_FLUX_TORQUE_CTRL_INIT Flux and torque controller (FluxTorqueController) with the
%   integral action of the bandwidth alpha_i (zero in observer-based V/Hz control).
self = struct('par', par, 'alpha_psi', alpha_psi, 'alpha_tau', alpha_tau, ...
    'alpha_i', alpha_i, 'x_psi', 0, 'x_tau', 0, 'i_a', complex(0), ...
    'u_ff', complex(0));
end

function [self, u_s_ref] = im_flux_torque_ctrl_compute_output(self, psi_s_ref, ...
    tau_M_ref, fbk)
%IM_FLUX_TORQUE_CTRL_COMPUTE_OUTPUT Stator voltage reference from the flux and
%   torque references.
par = self.par;
psi_s_abs = abs(fbk.psi_s);
% Auxiliary current (L_sgm = 0 in open-loop V/Hz control, where only the flux is
% controlled)
i_a = complex(0);
if par.L_sgm > 0
    i_a = fbk.psi_R/par.L_sgm;
end
% Torque-production factor and directions
c_tau = 1.5*par.n_p*real(i_a*conj(fbk.psi_s));
t_psi = complex(1);
t_tau = complex(0);
if c_tau > 0
    t_psi = 1.5*par.n_p*psi_s_abs*i_a/c_tau;
    t_tau = 1i*fbk.psi_s/c_tau;
end
% Error signals
e_psi = psi_s_ref - psi_s_abs;
e_tau = tau_M_ref - fbk.tau_M;
e_u = self.alpha_psi*e_psi*t_psi + self.alpha_tau*e_tau*t_tau;
u_i = self.x_psi*t_psi + self.x_tau*t_tau;
e_v = u_i - self.alpha_i*(psi_s_abs*t_psi + fbk.tau_M*t_tau);
% Voltage reference, consisting of the feedforward and integral action (u_ff) and
% the proportional action (e_u)
u_ff = par.R_s*fbk.i_s + 1i*fbk.w_s*fbk.psi_s + e_v;
% Workspace variables for the update
self.i_a = i_a;
self.u_ff = u_ff;
u_s_ref = u_ff + e_u;
end

function self = im_flux_torque_ctrl_update(self, T_s, fbk)
%IM_FLUX_TORQUE_CTRL_UPDATE Update the integral states with the realized voltage
%   fbk.u_s.
psi_s_abs = abs(fbk.psi_s);
% Error signal and gains
u_err = fbk.u_s - self.u_ff;
k_psi = 0;
if psi_s_abs > 0
    k_psi = self.alpha_i/psi_s_abs;
end
k_tau = 1.5*self.par.n_p*self.alpha_i;
% Update the integral states
self.x_psi = self.x_psi + T_s*k_psi*real(fbk.psi_s*conj(u_err));
self.x_tau = self.x_tau + T_s*k_tau*real(1i*self.i_a*conj(u_err));
end
